@Composable
fun SettingsScreen(viewModel:SettingsViewModel=hiltViewModel()){
    val settings by viewModel.settings.collectAsState();val message by viewModel.message.collectAsState();var remote by remember(settings.remoteDatabaseUrl){mutableStateOf(settings.remoteDatabaseUrl)}
    LazyColumn(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){
        item{ScreenHeader("Settings","Local preferences")}
        item{Card{Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Dark mode",fontWeight=FontWeight.Bold);Text("Stored only on this device",style=MaterialTheme.typography.bodySmall)};Switch(settings.darkMode,viewModel::dark)}}}
        item{Card{Column(Modifier.padding(16.dp)){Text("Remote database manifest",fontWeight=FontWeight.Bold);Text("Optional. The app remains fully usable without it.",style=MaterialTheme.typography.bodySmall);Spacer(Modifier.height(8.dp));OutlinedTextField(value=remote,onValueChange={remote=it},label={Text("HTTPS manifest URL")},modifier=Modifier.fillMaxWidth(),singleLine=true);Button(onClick={viewModel.remoteUrl(remote)},modifier=Modifier.align(Alignment.End)){Text("Save")}}}}
        message?.let{item{Text(it,color=MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.bodySmall)}}
        item{Card{Column(Modifier.padding(16.dp)){Text("Above-budget allowance",fontWeight=FontWeight.Bold);Text("${settings.allowAboveBudgetPercent}% when the employee explicitly enables it",style=MaterialTheme.typography.bodySmall);Slider(value=settings.allowAboveBudgetPercent.toFloat(),onValueChange={viewModel.aboveBudget(it.toInt())},valueRange=0f..25f,steps=24)}}}
        item{NoticeCard("No API keys or sensitive credentials are stored or exported. Admin PIN protection is local convenience protection, not enterprise-grade security.")}
    }
}

@Composable
fun DatabaseInfoScreen(online:Boolean,onAdmin:()->Unit,viewModel:HomeViewModel=hiltViewModel()){
    val products by viewModel.products.collectAsState();val software by viewModel.software.collectAsState();val version by viewModel.databaseVersion.collectAsState()
    Column(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){ScreenHeader("Database","Local source of truth"){OnlineBadge(online)};Card{Column(Modifier.padding(18.dp)){InfoRow("Version",version?:"Loading…");InfoRow("Products",products.size.toString());InfoRow("Software",software.size.toString());InfoRow("Operation","Offline-first")}};NoticeCard("Remote checks are optional. Updates are validated, backed up, and committed in one transaction; failures roll back without replacing the current catalog.");Button(onClick=onAdmin,modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.AdminPanelSettings,null);Spacer(Modifier.width(8.dp));Text("OPEN ADMIN / DATABASE")};if(!online)NoticeCard("Remote updates and official links are unavailable. Search, compatibility, recommendations, comparison and editing still work.")}
}

@Composable
fun AdminScreen(online:Boolean,viewModel:AdminViewModel=hiltViewModel()){
    val state by viewModel.state.collectAsState();val settings by viewModel.settings.collectAsState();if(!settings.adminPinConfigured){AdminPinSetup(state.message,viewModel::configurePin);return};if(!state.unlocked){AdminUnlock(state.message,viewModel::unlock);return}
    var tab by remember{mutableIntStateOf(0)};var showProduct by remember{mutableStateOf<ProductSpec?>(null)};var showProcessor by remember{mutableStateOf(false)};var showGpu by remember{mutableStateOf(false)};var showSoftware by remember{mutableStateOf(false)};var requirementFor by remember{mutableStateOf<SoftwareEntity?>(null)};var archiveCandidate by remember{mutableStateOf<ProductSpec?>(null)}
    val products by viewModel.productsFlow.collectAsState();val processors by viewModel.processors.collectAsState();val gpus by viewModel.gpus.collectAsState();val software by viewModel.software.collectAsState()
    Column(Modifier.fillMaxSize().padding(16.dp)){ScreenHeader("Admin / Database","Local PIN protection only"){IconButton(onClick=viewModel::lock){Icon(Icons.Default.Lock,"Lock")}};state.message?.let{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(it,Modifier.weight(1f),color=MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.bodySmall);if(state.undoArchiveId!=null)TextButton(onClick=viewModel::restoreArchived){Text("UNDO")}}};if(state.isBusy)LinearProgressIndicator(Modifier.fillMaxWidth());ScrollableTabRow(selectedTabIndex=tab,edgePadding=0.dp){listOf("Products","Hardware","Software","Import & backup").forEachIndexed{i,label->Tab(selected=tab==i,onClick={tab=i},text={Text(label)})}};Spacer(Modifier.height(10.dp));when(tab){0->AdminProducts(products,{showProduct=emptyProduct()},{showProduct=it},{id->archiveCandidate=products.firstOrNull{it.id==id}});1->AdminHardware(processors,gpus,{showProcessor=true},{showGpu=true});2->AdminSoftware(software,{showSoftware=true}){requirementFor=it};else->ImportBackupPane(online,state,viewModel)}}
    showProduct?.let{ProductEditor(it,processors,gpus,onDismiss={showProduct=null},onSave={viewModel.saveProduct(it);showProduct=null})};if(showProcessor)ProcessorEditor({showProcessor=false}){viewModel.saveProcessor(it);showProcessor=false};if(showGpu)GpuEditor({showGpu=false}){viewModel.saveGpu(it);showGpu=false};if(showSoftware)SoftwareEditor({showSoftware=false}){viewModel.saveSoftware(it);showSoftware=false};requirementFor?.let{app->RequirementEditor(app,{requirementFor=null}){viewModel.saveRequirement(it);requirementFor=null}};archiveCandidate?.let{product->AlertDialog(onDismissRequest={archiveCandidate=null},title={Text("Archive product?")},text={Text("${product.displayName} will disappear from staff search and recommendations. You can undo immediately after archiving.")},confirmButton={Button(onClick={viewModel.archiveProduct(product.id);archiveCandidate=null}){Text("Archive")}},dismissButton={TextButton(onClick={archiveCandidate=null}){Text("Cancel")}})}
}

@Composable private fun AdminPinSetup(message:String?,configure:(String)->Unit){var pin by remember{mutableStateOf("")};var confirm by remember{mutableStateOf("")};Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Card(Modifier.widthIn(max=440.dp).padding(20.dp)){Column(Modifier.padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(10.dp)){Icon(Icons.Default.EnhancedEncryption,null,Modifier.size(48.dp));Text("Create admin PIN",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Set a device-specific PIN before editing catalog data.",style=MaterialTheme.typography.bodySmall);OutlinedTextField(pin,{pin=it.filter(Char::isDigit).take(12)},label={Text("New PIN (4–12 digits)")},visualTransformation=PasswordVisualTransformation(),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.NumberPassword));OutlinedTextField(confirm,{confirm=it.filter(Char::isDigit).take(12)},label={Text("Confirm PIN")},visualTransformation=PasswordVisualTransformation(),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.NumberPassword));if(confirm.isNotBlank()&&pin!=confirm)Text("PINs do not match.",color=MaterialTheme.colorScheme.error);message?.let{Text(it,color=MaterialTheme.colorScheme.error)};Button(onClick={configure(pin)},enabled=pin.length>=4&&pin==confirm,modifier=Modifier.fillMaxWidth()){Text("SAVE PIN & CONTINUE")}}}}}
@Composable private fun AdminUnlock(message:String?,unlock:(String)->Unit){var pin by remember{mutableStateOf("")};Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Card(Modifier.widthIn(max=420.dp).padding(20.dp)){Column(Modifier.padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.AdminPanelSettings,null,Modifier.size(48.dp));Text("Admin Mode",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Local protection — not enterprise security",style=MaterialTheme.typography.bodySmall);Spacer(Modifier.height(12.dp));OutlinedTextField(pin,{pin=it.filter(Char::isDigit).take(12)},label={Text("PIN")},visualTransformation=PasswordVisualTransformation(),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.NumberPassword));message?.let{Text(it,color=MaterialTheme.colorScheme.error)};Spacer(Modifier.height(10.dp));Button({unlock(pin)},Modifier.fillMaxWidth()){Text("UNLOCK")}}}}}

@Composable private fun AdminProducts(products:List<ProductSpec>,add:()->Unit,edit:(ProductSpec)->Unit,archive:(Long)->Unit){Column{Button(add,Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Text(" Add product")};Spacer(Modifier.height(8.dp));LazyColumn(verticalArrangement=Arrangement.spacedBy(7.dp)){items(products,key={it.id}){p->OutlinedCard{Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(p.displayName,fontWeight=FontWeight.Bold);Text(p.sku,style=MaterialTheme.typography.bodySmall)};IconButton({edit(p)}){Icon(Icons.Default.Edit,"Edit")};IconButton({archive(p.id)}){Icon(Icons.Default.Archive,"Archive")}}}}}}}
