@Composable private fun ImportBackupPane(online:Boolean,state:AdminUiState,viewModel:AdminViewModel){val context=LocalContext.current;val scope=rememberCoroutineScope();var exportBytes by remember{mutableStateOf<ByteArray?>(null)};val open=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->uri?.let{context.contentResolver.openInputStream(it)?.use{stream->viewModel.previewImport(stream.readBytes(),it.lastPathSegment?:"database.json")}}};val create=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){uri->uri?.let{target->exportBytes?.let{bytes->context.contentResolver.openOutputStream(target)?.use{it.write(bytes)}}}};LazyColumn(verticalArrangement=Arrangement.spacedBy(9.dp)){item{Button({open.launch(arrayOf("application/json","application/zip","text/csv"))},Modifier.fillMaxWidth(),enabled=!state.isBusy){Icon(Icons.Default.FileOpen,null);Text(" Import JSON / ZIP package")}};state.preview?.let{preview->item{Card{Column(Modifier.padding(14.dp)){Text("Import preview",fontWeight=FontWeight.Bold);Text("${preview.productCount} products • ${preview.softwareCount} software • version ${preview.version?:"unknown"}");preview.errors.take(10).forEach{Text("Error: ${it.record}: ${it.message}",color=MaterialTheme.colorScheme.error,style=MaterialTheme.typography.bodySmall)};if(preview.errors.size>10)Text("${preview.errors.size-10} more errors not shown",style=MaterialTheme.typography.labelSmall);preview.warnings.take(5).forEach{Text("Warning: ${it.record}: ${it.message}",style=MaterialTheme.typography.bodySmall)};Button(viewModel::commitImport,enabled=preview.canImport&&!state.isBusy,modifier=Modifier.fillMaxWidth()){Text("VALIDATE & IMPORT")}}}}};item{OutlinedButton({scope.launch{exportBytes=viewModel.exportBytes();create.launch("JI_PRODUCT_DATABASE_BACKUP.json")}},Modifier.fillMaxWidth(),enabled=!state.isBusy){Icon(Icons.Default.SaveAlt,null);Text(" Export backup")}};item{Button(viewModel::checkUpdate,enabled=online&&!state.isBusy,modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.SystemUpdate,null);Text(" Check remote update")}};item{OutlinedButton(onClick=viewModel::clearLocalHistory,modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.DeleteSweep,null);Text(" Clear local searches & shortcuts")}};item{NoticeCard("Every import is validated first. A local safety backup is created before the database is replaced, and the transaction rolls back automatically if any write fails.")};item{PinChange(viewModel::setPin)}}}
@Composable private fun PinChange(setPin:(String)->Unit){var pin by remember{mutableStateOf("")};OutlinedCard{Column(Modifier.padding(14.dp)){Text("Change admin PIN",fontWeight=FontWeight.Bold);OutlinedTextField(pin,{pin=it.filter(Char::isDigit)},label={Text("New PIN (4+ digits)")},visualTransformation=PasswordVisualTransformation(),singleLine=true,modifier=Modifier.fillMaxWidth());Button({setPin(pin)},enabled=pin.length>=4,modifier=Modifier.align(Alignment.End)){Text("Update PIN")}}}}

