extField(price,{price=it.filter{c->c.isDigit()||c=='.'}},label={Text("Price")},singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),modifier=Modifier.fillMaxWidth());Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedTextField(ram,{ram=it.filter(Char::isDigit)},label={Text("RAM GB")},singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),modifier=Modifier.weight(1f));OutlinedTextField(storage,{storage=it.filter(Char::isDigit)},label={Text("Storage GB")},singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),modifier=Modifier.weight(1f))};OutlinedTextField(os,{os=it},label={Text("Operating system")},singleLine=true,modifier=Modifier.fillMaxWidth());OptionalSelector("Processor",cpus,cpu,{"${it.manufacturer} ${it.model}"},noneText="Not specified"){cpu=it};OptionalSelector("GPU",gpus,gpu,{"${it.manufacturer} ${it.model}"},noneText="Not specified"){gpu=it}}},confirmButton={Button({onSave(initial.copy(sku=sku.trim(),brand=brand.trim(),model=model.trim(),category=category,availabilityStatus=availability,price=price.toDouble(),ramGB=ram.toIntOrNull(),storageGB=storage.toIntOrNull(),operatingSystem=os.trim().takeIf(String::isNotBlank),processor=cpu?.toDomain(),gpu=gpu?.toDomain(),verificationStatus=VerificationStatus.UNVERIFIED,lastUpdated=java.time.LocalDate.now().toString()))},enabled=valid){Text("Save")}},dismissButton={TextButton(onDismiss){Text("Cancel")}})}

